      section2Title: "2. Beschreibung des Dienstes",
      section2Content: "LodgeTrack ist eine Plattform für Unterkunftsverwaltung, mit der Buchungen, Umsatz, Auslastung und Ausgaben über Ihr Unterkunftsportfolio hinweg nachverfolgt werden. Wir stellen die Software wie sie ist bereit und behalten uns das Recht vor, Funktionen jederzeit zu ändern.",
