      section4Content: "Ihre Daten gehören Ihnen. Wir verkaufen Ihre Daten nicht. Einzelheiten dazu, wie wir Ihre Informationen erheben, verwenden und schützen, finden Sie in unserer Datenschutzerklärung.",
      privacyPolicyLink: "Unsere Datenschutzerklärung lesen",
      section5Title: "5. Abonnement und Abrechnung",
      section5Content: "LodgeTrack bietet kostenlose und kostenpflichtige Pläne. Die Abrechnung läuft über unseren Zahlungsanbieter. Sie können jederzeit kündigen. Erstattungen richten sich nach den Richtlinien unseres Zahlungsanbieters.",
      section6Title: "6. Zulässige Nutzung",
      section6Content: "Sie dürfen LodgeTrack nicht für rechtswidrige Aktivitäten nutzen, geistiges Eigentum verletzen oder den Betrieb des Dienstes stören.",
      section7Title: "7. Gewährleistungsausschluss",
      section7Content: "LodgeTrack wird „wie besehen“ und ohne Gewährleistungen jedweder Art bereitgestellt. Wir garantieren keinen unterbrechungsfreien oder fehlerfreien Dienst.",
      section8Title: "8. Haftungsbeschränkung",
      section8Content: "Im größtmöglichen gesetzlich zulässigen Umfang haftet LodgeTrack nicht für indirekte, zufällige oder Folgeschäden.",
